/* Local-only interface styles. No remote fonts, images, or CDN assets. */

/*
 * Warm-dark tokens reconstructed from the reference screenshot as starting
 * values (UX-01). They are approximate calibration targets, not exact
 * Superhuman values; geometry is calibrated on real displays later.
 */
:root {
  color-scheme: dark;
  font-family: var(--font-ui);
  /*
   * Type scale (DESIGN.md "Typography"): one local system sans, a fixed rem
   * scale, two weights. Hierarchy comes from weight (600 vs 400) and tone
   * (Paper White vs Ash), not from extra sizes.
   */
  --font-ui: system-ui, -apple-system, sans-serif;
  --font-mono: ui-monospace, monospace;
  /* 16px: split tabs, context title, contact name, drawer and reader headings. */
  --type-headline: 1rem;
  /* 12px: everything else in the app shell (rows, rail, panes, drawers, reader chrome). */
  --type-body: 0.75rem;
  /* 11px: split-tab counts only. */
  --type-count: 0.6875rem;
  /* Plain-text message bodies in the reader (monospace runs visually larger). */
  --type-mono: 0.85rem;
  /* 15px: prose message bodies in the reader (proportional face). */
  --type-reading: 0.9375rem;
  --weight-regular: 400;
  --weight-strong: 600;
  --leading-headline: 1.25;
  --leading-ui: 1.35;
  --leading-mono: 1.45;
  --leading-reading: 1.6;
  --surface: #292826;
  --surface-contact: #1f1e1c;
  --surface-raised: #33312e;
  --focus-fill: #474644;
  --focus-accent: #bba5ed;
  /* DESIGN.md Paper White: 14.7:1 on Warm Charcoal, 9.4:1 on Focus Stone. */
  --text-primary: #ffffff;
  /* DESIGN.md Ash: >=4.5:1 on Focus Stone (4.99:1; the old #a8a29a was 3.73:1). */
  --text-secondary: #c0bcb6;
  /* DESIGN.md Smoke (inactive split tabs, on Warm Charcoal only: 5.4:1) and
     Graphite (resting glyphs). */
  --text-tertiary: #a09c9a;
  --icon-muted: #8e8a87;
  /* DESIGN.md split-header height: content top to the first row. */
  --split-header-height: 78px;
  --unread-marker: #ce9ece;
  /* DESIGN.md Seam: the 1px vertical separators between rail, list and
     contact pane (and the drawer's leading edge), utility-chip and input
     borders. Never between rows. */
  --divider: #474543;
  /* Quieter structural rule inside a pane (reader message stack, drawer list
     rows): the pre-polish Seam value, kept so the reader and drawers do not
     change tone until a reader reference is captured. */
  --rule: #3b3936;
  /* Overlay lift (DESIGN.md "Elevation"): palette/navigator and the modal
     attachment chooser, over a dimmed shell. */
  --overlay-backdrop: rgba(0, 0, 0, 0.53);
  --overlay-lift: 0 16px 64px rgba(0, 0, 0, 0.53);
  /* DESIGN.md Inkwell (rail destination pill) and Rail Pebble (28px circle,
     active destination). */
  --rail-well: #141413;
  --rail-button: #383735;
  /* Pane geometry shared by the rail and the contact pane so their lines
     follow the list column: the split-tab line is centered 42px down (6px
     header pad + half of its 72px row), the first list line is the 36px row
     right below the 78px header. */
  --rail-width: 40px;
  --contact-width: 272px;
  --contact-inset: 24px;
  --tab-line: 42px;
  --first-line: calc(var(--split-header-height) + 18px);
  --warning: #e4c465;
  --danger: #f1a9a5;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
}

/*
 * Buttons (DESIGN.md "Buttons"). Zero-specificity defaults so every component
 * class (split tabs, rail and row glyphs, contact lines) keeps its own look.
 *
 * Ghost (the default, browsing shell): transparent, Paper White text, 4px
 * radius, 24px tall at the 12px shell size (4px block padding) so the hit
 * target matches the old bordered chip. Hover lifts to Lifted Charcoal.
 */
:where(button) {
  background: transparent;
  color: var(--text-primary);
  border: 0;
  border-radius: 4px;
  padding: 4px 8px;
  font: inherit;
  cursor: pointer;
}

:where(button:not(:disabled):hover) {
  background: var(--surface-raised);
}

/* On the raised composer surfaces the ghost hover fill equals the card
   background, so it would be invisible; use the stronger fill there. */
:where(.compose-card, .reply-composer) :where(button:not(:disabled):hover) {
  background: var(--focus-fill);
}

:where(button:not(:disabled):active) {
  background: var(--focus-fill);
}

:where(button:disabled) {
  opacity: 0.45;
  cursor: default;
}

/*
 * Utility chip: a Lifted Charcoal fill with a 1px Seam border, only inside
 * utility drawers, the modal attachment chooser, recovery banners and the
 * synthetic workspace strip. Same 24px height as the ghost button.
 */
:where(.utility-drawer, .attachment-chooser, .recovery-banner, .header-alert, .workspace-header) :where(button) {
  background: var(--surface-raised);
  border: 1px solid var(--divider);
  padding: 3px 8px;
}

:where(.utility-drawer, .attachment-chooser, .recovery-banner, .header-alert, .workspace-header) :where(button:not(:disabled):hover) {
  background: var(--focus-fill);
}

button:focus-visible {
  outline: 2px solid var(--focus-accent);
